#!/usr/bin/env bash
# Run:ai cluster component (after the k0rdent catalog runai-cp install; the catalog covers only the control plane)
# Installed 2026-10-16 23:05 UTC on gpu-cluster: release runai-cluster, namespace runai, chart runai-cluster 3.0.20
# Source: command generated by the Run:ai UI onboarding wizard (cluster gpu-cluster, location "Same as the control plane"),
#         edited as described below. NVIDIA doc: docs/installation-and-configuration/installation/install-using-helm/helm-install.md
#
# The bootstrap token is single-use and expires 2 hours after the wizard generates it, so it is NOT stored here.
# To reinstall, generate a new command in the UI (Clusters) and paste its token below.
#
# Changes from the wizard-generated command:
#   - helm repo "runai" -> https://helm.ngc.nvidia.com/nvidia/runai-oss  (wizard assumes .../nvidia/runai = paid repo -> 403 Forbidden)
#   - --version 2.26.50 -> 3.0.20   (2.26.50 is not in the open-source repo; must match control plane 3.0.20)
#   - ingressClass haproxy -> nginx (gpu-cluster runs ingress-nginx)
#   - added clusterConfig.global.subdomainSupport=false (path-based workspace URLs; no wildcard DNS/cert)
#   - kai-resource-management.kai-scheduler.global.nvFractions.set: false on 2026-10-17 (helm rev 2), back to TRUE on
#     2026-10-20 (helm rev 3) after the GPU stack upgrade (k0s 1.36.3 / containerd 2.3.3 / GPU Operator 26.7.2 /
#     driver 615.71.09 / toolkit 1.20.1). Only set it to true on a cluster that meets those requirements.
#   - (history) with nvFractions=false: added 2026-10-17, helm revision 2
#       GPU Operator 25.3.0 ships NVIDIA container toolkit v1.17.5; gpu-fractioning needs >= v1.20.1. With it enabled,
#       its GpuFractioningConfig reports Ready=False, the control plane marks the required gpu-stack dependency
#       unavailable, and the UI does not show the cluster as connected. NOTE: Helm creates GpuFractioningConfig/default
#       as a post-install hook, so disabling the subchart later does NOT delete it - see README section 9.
#
# Wizard original (token removed):
#   helm upgrade -i runai-cluster runai/runai-cluster -n runai \
#   --set controlPlane.url=runai.lab.example.com \
#   --set controlPlane.bootstrapToken=<TOKEN> \
#   --set cluster.uid=<CLUSTER_UID> \
#   --set cluster.url=https://runai.lab.example.com --version="2.26.50" --create-namespace \
#   --set clusterConfig.global.ingress.ingressClass=haproxy \
#   --set global.fipsMode=off

set -euo pipefail
export KUBECONFIG=~/gpu-cluster.kubeconfig
[ "$(kubectl config current-context)" = "gpu-cluster-admin@gpu-cluster" ] || { echo "wrong cluster context"; exit 1; }

BOOTSTRAP_TOKEN="${BOOTSTRAP_TOKEN:?set BOOTSTRAP_TOKEN to the token from the Run:ai UI wizard}"

helm repo add runai https://helm.ngc.nvidia.com/nvidia/runai-oss --force-update
helm repo update runai

helm upgrade -i runai-cluster runai/runai-cluster -n runai \
--set controlPlane.url=runai.lab.example.com \
--set controlPlane.bootstrapToken="${BOOTSTRAP_TOKEN}" \
--set cluster.uid=<CLUSTER_UID> \
--set cluster.url=https://runai.lab.example.com --version="3.0.20" --create-namespace \
--set clusterConfig.global.ingress.ingressClass=nginx \
--set clusterConfig.global.subdomainSupport=false \
--set kai-resource-management.kai-scheduler.global.nvFractions.set=true \
--set global.fipsMode=off

# Verify
kubectl get pods -n runai
kubectl get runaiconfig runai -n runai
kubectl get cm runai-public -n runai -o jsonpath="{.data.cluster-version}"; echo
